 def regexp_extract_all(
     str: ColumnOrName, regexp: ColumnOrName, idx: t.Optional[t.Union[int, Column]] = None
 ) -> Column:
@@
     if idx is None:
         return Column.invoke_expression_over_column(str, expression.RegexpExtractAll, expression=regexp)
     else:
         idx = lit(idx) if isinstance(idx, int) else idx
+        if Column.ensure_col(idx).expression.name == "1":
+            return Column.invoke_anonymous_function(str, "regexp_extract_all", regexp, idx)
         return Column.invoke_expression_over_column(
             str, expression.RegexpExtractAll, expression=regexp, group=idx
         )
